/** Refuse a screenshot receipt when its target is hidden by the viewport or a scrolling ancestor. */
export function assertResignationCaptureVisibility(metrics,id){
 assert(metrics.bounds.width>0&&metrics.bounds.height>0,id+' target is empty');
 assert(metrics.clip.height>40&&metrics.clip.width>0,id+' has no available app viewport');
 assert(metrics.visibleHeight>=Math.min(metrics.bounds.height,metrics.clip.height-20),id+' target is clipped beyond its available app viewport');
 assert(metrics.visibleWidth>=Math.min(metrics.bounds.width,metrics.clip.width)-1,id+' target is horizontally clipped');
}
export function validateResignationFixture(value){
 assert.equal(value?.fixture?.version,2);assert.equal(value?.preparationOnly,true);const f=value.fixture;assert.equal(value.normalEmailObservation?.identityCount,12,'All fictional actors require explicit native delivery identities');
 assert.deepEqual(f.actors.map(a=>a.key).sort(),['accept','bp','ceo','configurer','decline','gbs','manager','outsider','recall','retain','unconfigured','upload']);
 const uuid=v=>typeof v==='string'&&/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(v);
 assert(uuid(f.uploadDepartmentId)&&uuid(f.uploadEmailId)&&uuid(f.uploadWorkflowId)&&uuid(f.uploadGroupId)&&uuid(f.postingApproverGroupId)&&uuid(f.acceptanceWorkflowId)&&uuid(f.receivedEmailId)&&uuid(f.acceptanceEmailId)&&uuid(f.retentionEmailId));assert(/^\d{4}-\d{2}-\d{2}$/.test(f.correctedLastWorkingDay)&&f.correctedLastWorkingDay>f.lastWorkingDay);assert.equal(typeof f.acceptanceWorkflowName,'string');assert(f.acceptanceWorkflowName.trim()&&f.workflowIds.includes(f.acceptanceWorkflowId));assert(uuid(f.tenantId)&&uuid(f.companyId)&&typeof f.groupId==='string'&&f.groupId.length>0);assert(uuid(f.normalDepartmentId)&&uuid(f.gapDepartmentId)&&f.normalDepartmentId!==f.gapDepartmentId);assert.equal(new Set(f.actors.map(a=>a.userId)).size,12);assert(f.actors.every(a=>uuid(a.userId)));assert.equal(f.workflowIds.length,11);assert(uuid(f.repairWorkflowId)&&typeof f.acceptanceLetterName==='string'&&typeof f.retentionLetterName==='string');assert(f.workflowIds.every(uuid));assert.equal(f.privateSentinel,'RJ_BROWSER_PRIVATE_93017');assert.equal(f.roleBindings.length,3);for(const role of ['gbs','ceo','bp']){const binding=f.roleBindings.find(binding=>binding.role===role);assert(binding&&binding.userId===f.actors.find(actor=>actor.key===role)?.userId&&binding.groupId);assert(uuid(f.actors.find(actor=>actor.key===role)?.personId));}assert.equal(Object.values(value.cases).flat().length,0,'Preparation must precede browser submissions');return f;
}
